create table public.rental_process_tenants (id uuid default gen_random_uuid() not null, organization_id uuid default current_organization_id() not null, process_id uuid not null, tenant_id uuid not null, responsibility text default 'co_responsible' not null, created_at timestamptz default now() not null);
create table public.rental_processes (id uuid default gen_random_uuid() not null, organization_id uuid default current_organization_id() not null, property_id uuid not null, lead_id uuid, primary_tenant_id uuid, stage text default 'available' not null, analysis_status text default 'pending' not null, declared_income numeric(14,2), documents_presented boolean default false not null, income_proof_presented boolean default false not null, analysis_notes text, proposal_rent numeric(14,2), next_action_at timestamptz, assigned_to uuid, lost_reason text, created_by uuid default auth.uid(), created_at timestamptz default now() not null, updated_at timestamptz default now() not null);
create table public.rental_stage_history (id bigint generated always as identity not null, rental_case_id uuid not null, property_id uuid not null, lead_id uuid, from_stage text, to_stage text not null, changed_by uuid, created_at timestamptz default now() not null);
create table public.rental_status_history (id bigint generated always as identity not null, organization_id uuid not null, contract_id uuid not null, from_status text, to_status text not null, changed_by uuid, created_at timestamptz default now() not null);
create table public.rental_tenants (id uuid default gen_random_uuid() not null, organization_id uuid default current_organization_id() not null, full_name text not null, cpf text, phone text, email text, profession text, monthly_income numeric(14,2), income_proof text, references_text text, residents text, notes text, created_by uuid default auth.uid(), created_at timestamptz default now() not null, updated_at timestamptz default now() not null);
create table public.rental_transfers (id uuid default gen_random_uuid() not null, organization_id uuid default current_organization_id() not null, contract_id uuid not null, charge_id uuid not null, gross_received numeric(14,2) default 0 not null, admin_fee numeric(14,2) default 0 not null, other_expenses numeric(14,2) default 0 not null, transfer_value numeric(14,2) default 0 not null, status text default 'pending' not null, due_date date, paid_at date, notes text, created_at timestamptz default now() not null, updated_at timestamptz default now() not null);
create table public.response_templates (id uuid default gen_random_uuid() not null, name text not null, channel text default 'all' not null, content text not null, sort_order integer default 0 not null, active boolean default true not null, created_at timestamptz default now() not null, updated_at timestamptz default now() not null);
create table public.site_events (id bigint generated always as identity not null, session_id text not null, event_type text not null, property_id uuid, path text not null, metadata jsonb default '{}'::jsonb not null, created_at timestamptz default now() not null);
create table public.site_visits (id bigint generated always as identity not null, session_id text not null, path text not null, page_type text, property_id uuid, referrer text, utm_source text, utm_medium text, utm_campaign text, created_at timestamptz default now() not null);
create table public.social_messages (id bigint generated always as identity not null, lead_id uuid, platform text not null, channel text not null, external_message_id text, external_sender_id text, direction text default 'inbound' not null, message_text text, sent_at timestamptz, metadata jsonb default '{}'::jsonb not null, created_at timestamptz default now() not null, external_recipient_id text, read_at timestamptz, delivery_status text default 'received' not null, error_message text);
create table public.team_activity_log (id bigint generated by default as identity not null, organization_id uuid, actor_user_id uuid, table_name text not null, record_id text, action text not null, changed_fields jsonb default '[]'::jsonb not null, created_at timestamptz default now() not null);;
